const paths={layers:'M12 3 2 8l10 5 10-5-10-5ZM2 12l10 5 10-5M2 16l10 5 10-5',plus:'M12 5v14M5 12h14',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',folder:'M3 7V5a1 1 0 0 1 1-1h5l2 3h9a1 1 0 0 1 1 1v11a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V7Z',file:'M14 2H5v20h14V7l-5-5ZM14 2v6h5M8 12h8M8 16h6',chevron:'m9 5 7 7-7 7',close:'m6 6 12 12M6 18 18 6',more:'M5 12h.01M12 12h.01M19 12h.01',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9L12 3Z',copy:'M9 9h12v12H9V9ZM15 5V3H3v12h2',cloud:'M6 18h12a4 4 0 0 0 .6-8A7 7 0 0 0 5 8a5 5 0 0 0 1 10Z',lock:'M5 10h14v11H5V10ZM8 10V6a4 4 0 0 1 8 0v4',key:'M15 3a6 6 0 1 1-4 10l-7 7H2v-3l7-7a6 6 0 0 1 6-7ZM16 7h.01',check:'m5 12 4 4L19 6',arrow:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',upload:'M12 16V3m-5 5 5-5 5 5M4 17v4h16v-4',edit:'m15 5 4 4M3 21l4-1L21 6l-4-4L3 16v5Z',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12ZM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',split:'M3 3h18v18H3V3ZM12 3v18',help:'M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4M12 17h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',menu:'M3 5h18M3 12h18M3 19h18',variable:'m8 4-5 8 5 8M16 4l5 8-5 8M14 3l-4 18',refresh:'M20 7V3l-3 3A8 8 0 1 0 20 16M20 3h-5',move:'M12 2v20M2 12h20m-4-4 4 4-4 4M8 6l4-4 4 4',bookmark:'M6 3h12v18l-6-4-6 4V3Z'};
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
