let pendingChange='edit',historyPreview=null;
let state=freshState();
let session={name:'私人工作区'},etag=null,mode='edit',query='',saveTimer,previewTimer,toastTimer,dirty=false,syncing=false,conflict=false,revision=0,selectedFolder=null,variablesCollapsed=false;
const current=()=>state.prompts.find(p=>p.id===state.active);
