 'rename-prompt':id=>{const p=state.prompts.find(x=>x.id===id);nameDialog('重命名 Prompt',p.title,name=>{p.title=name;changed();renderTabs();renderSidebar();renderBookmarks();renderDocument();});},
 'move-prompt':id=>{const p=state.prompts.find(x=>x.id===id);modal(`${modalHead('移动 Prompt',p.title)}<form><label class="form-field">目标文件夹<select name="folder">${folderOptions(p.folder)}</select></label>${modalFoot('移动')}</form>`,data=>{movePromptPresets(state,p,data.get('folder')||null);p.folder=data.get('folder')||null;const f=state.folders.find(x=>x.id===p.folder);if(f)f.open=true;changed();renderSidebar();renderDocument();$('#modal').close();});},
