 'collapse-variables':()=>{variablesCollapsed=!variablesCollapsed;renderVariables();},'copy':copyPrompt,'presets':presetLibrary,'save-preset':()=>savePreset(),
 'edit-preset':savePreset,'apply-preset':id=>{const p=current(),preset=presetsForPrompt(state,p).find(x=>x.id===id);if(!preset){toast('此组合不属于当前文件夹或 Prompt');return;}const names=variableNames(p.body);const match=names.filter(k=>Object.hasOwn(preset.values,k));if(!match.length){toast('这个组合与当前 Prompt 没有同名变量');return;}for(const k of match)p.values[k]=preset.values[k];changed();renderVariables();preview();$('#modal').close();toast(`已填入 ${match.length} 个变量`);},
