document.addEventListener('click',async e=>{const btn=e.target.closest('[data-action]');if(!btn)return;const menu=btn.closest('#folder-context-menu');if(menu){const rect=menu.getBoundingClientRect();panelOrigin={x:rect.left,y:rect.top};panelReturnFocus=folderMenuAnchor;closeFolderMenu();}else if(!btn.closest('#modal'))rememberPanelOrigin(btn);try{if(!await guardDocumentAction(btn.dataset.action,btn.dataset.id))return;await actions[btn.dataset.action]?.(btn.dataset.id,btn);}catch(error){console.error(error);toast(error.message||'操作未完成，请重试');}});
